     1	/**
     2	 * Query-time search plus the write-time index maintenance driven by `search.reindex_requested`.
     3	 *
     4	 * Must call (do not reimplement): assertCan, assertOrgScope, subscribe, isEnabled, consumeRateLimit
     5	 */
     6	import { subscribe } from "@/lib/event-bus";
     7	import { isEnabled } from "@/lib/feature-flags";
     8	import { assertCan } from "@/lib/permissions";
     9	import { consumeRateLimit } from "@/lib/rate-limit";
    10	import { assertOrgScope } from "@/lib/tenant";
    11	import * as commentRepo from "@/server/repositories/comment-repository";
    12	import * as issueRepo from "@/server/repositories/issue-repository";
    13	import * as orgRepo from "@/server/repositories/organization-repository";
    14	import * as projectRepo from "@/server/repositories/project-repository";
    15	import * as searchRepo from "@/server/repositories/search-repository";
    16	import { orgResource } from "./_support";
    17	import type { SearchQueryInput } from "@/schemas/search";
    18	import type { SearchSubjectKind } from "@/server/repositories/search-repository";
    19	import type { Comment } from "@/types/comment";
    20	import type { OrgId, Page } from "@/types/common";
    21	import type { Unsubscribe } from "@/types/event";
    22	import type { Issue } from "@/types/issue";
    23	import type { Actor } from "@/types/member";
    24	import type { Project } from "@/types/project";
    25	
    26	export type SearchHit = {
    27	  kind: SearchSubjectKind;
    28	  id: string;
    29	  title: string;
    30	  snippet: string;
    31	  href: string;
    32	};
    33	
    34	/** Characters of surrounding context kept on either side of a match. */
    35	const SNIPPET_RADIUS = 60;
    36	
    37	/** Token bucket protecting the index from query bursts. */
    38	const SEARCH_QUERY_BUCKET = "search:query";
    39	
    40	/**
    41	 * Runs a query against the denormalised index. Field-scoped syntax
    42	 * (`status:done`) is an `advanced_search` feature, so a query containing a
    43	 * colon is rejected for plans that do not include it rather than silently
    44	 * being treated as literal text.
    45	 */
    46	export async function search(
    47	  actor: Actor,
    48	  input: SearchQueryInput,
    49	): Promise<Page<SearchHit>> {
    50	  assertOrgScope(actor, input.orgId);
    51	  assertCan(actor, "issue:read", orgResource(input.orgId));
    52	
    53	  const verdict = await consumeRateLimit(input.orgId, SEARCH_QUERY_BUCKET);
    54	  if (!verdict.allowed) {
    55	    throw new Error(
    56	      `Search rate limit reached; try again after ${verdict.resetAt}`,
    57	    );
    58	  }
    59	
    60	  const org = await orgRepo.findOrgById(input.orgId);
    61	  const advanced = isEnabled("advanced_search", {
    62	    orgId: input.orgId,
    63	    userId: actor.userId,
    64	    plan: org?.plan ?? "free",
    65	    role: actor.role,
    66	    overrides: org?.settings.enabledFlagOverrides,
    67	  });
    68	
    69	  if (input.q.includes(":") && !advanced) {
    70	    throw new Error("Field-scoped search is not included in this plan");
    71	  }
    72	
    73	  const page = await searchRepo.searchDocuments(input);
    74	
    75	  return {
    76	    items: page.items.map((row) => ({
    77	      kind: row.subjectKind,
    78	      id: row.subjectId,
    79	      title: row.content.split("\n")[0] ?? row.subjectId,
    80	      snippet: snippetAround(row.content, input.q),
    81	      href: hrefFor(row.subjectKind, row.subjectId),
    82	    })),
    83	    nextCursor: page.nextCursor,
    84	    total: page.total,
    85	  };
    86	}
    87	
    88	export async function indexIssue(orgId: OrgId, issue: Issue): Promise<void> {
    89	  await searchRepo.upsertSearchDocument(
    90	    orgId,
    91	    "issue",
    92	    issue.id,
    93	    [issue.title, issue.description ?? ""].join("\n"),
    94	    issue.projectId,
    95	  );
    96	}
    97	
    98	export async function indexComment(
    99	  orgId: OrgId,
   100	  comment: Comment,
   101	): Promise<void> {
   102	  await searchRepo.upsertSearchDocument(
   103	    orgId,
   104	    "comment",
   105	    comment.id,
   106	    comment.body,
   107	    null,
   108	  );
   109	}
   110	
   111	export async function indexProject(
   112	  orgId: OrgId,
   113	  project: Project,
   114	): Promise<void> {
