/**
 * Next per-project issue number. A number is never reissued: the project's
 * high-water mark covers issues that have since been moved away, and the max
 * over the rows covers any that were written without going through the mark.
 */
export async function nextIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const db = getDb();
  const mark = db
    .select({ value: issueNumberMarks.highestNumber })
    .from(issueNumberMarks)
    .where(
      and(
        orgPredicate(issueNumberMarks.orgId, orgId),
        eq(issueNumberMarks.projectId, projectId),
      ),
    )
    .get();
  const row = db
    .select({ value: sql<number | null>`max(${issues.number})` })
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
    )
    .get();
  return Math.max(mark?.value ?? 0, row?.value ?? 0) + 1;
}

/** Raises a project's high-water mark to `issueNumber`; never lowers it. */
function markIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
  issueNumber: number,
): void {
  getDb()
    .insert(issueNumberMarks)
    .values({ orgId, projectId, highestNumber: issueNumber })
    .onConflictDoUpdate({
      target: issueNumberMarks.projectId,
      set: {
        highestNumber: sql`max(${issueNumberMarks.highestNumber}, excluded.highest_number)`,
      },
    })
    .run();
}

