/**
 * Files an issue under `toProjectId` with `toNumber`, the number the target
 * allocated for it. The source project keeps the number the issue leaves
 * behind: its mark is raised before the row moves, so it is never reissued
 * (ADR 0011). Labels, comments and attachments stay attached to the issue.
 */
export async function moveIssueToProject(
  orgId: OrgId,
  issueId: IssueId,
  toProjectId: ProjectId,
  toNumber: number,
): Promise<Issue> {
  const db = getDb();
  const current = db
    .select()
    .from(issues)
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .get();

  if (!current) throw new Error(`Issue ${issueId} not found`);

  markIssueNumber(orgId, current.projectId as ProjectId, current.number);
  markIssueNumber(orgId, toProjectId, toNumber);

  const row = db
    .update(issues)
    .set({
      projectId: toProjectId,
      number: toNumber,
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .returning()
    .get();

  const labels = await listLabelsForIssues(orgId, [issueId]);
  return toIssue(row, (labels[issueId] ?? []).map((label) => label.id));
}

