describe("services/issue-service moveIssueToProject", () => {
  it("re-files the issue under the target's next number and never reissues the old one", async () => {
    const moving = await createTenant("issuemove");
    const other = await insertOtherProject(moving);
    const first = await issueService.createIssue(
      moving.actors.member,
      issueInput(moving.org.id, moving.project.id, { title: "First" }),
    );
    const second = await issueService.createIssue(
      moving.actors.member,
      issueInput(moving.org.id, moving.project.id, { title: "Second" }),
    );
    expect(second.number).toBe(2);

    const received: unknown[] = [];
    const off = subscribe("issue.moved", (payload) => {
      received.push(payload);
    });

    try {
      const moved = await issueService.moveIssueToProject(moving.actors.member, {
        orgId: moving.org.id,
        issueId: second.id,
        toProjectId: other.id,
      });

      expect(moved).toMatchObject({
        id: second.id,
        projectId: other.id,
        number: 1,
        title: "Second",
        status: second.status,
      });
      expect(received).toEqual([
        expect.objectContaining({
          issueId: second.id,
          fromProjectId: moving.project.id,
          toProjectId: other.id,
          fromNumber: 2,
          toNumber: 1,
        }),
      ]);
    } finally {
      off();
    }

    // The source project's next issue skips the number the moved issue left.
    const third = await issueService.createIssue(
      moving.actors.member,
      issueInput(moving.org.id, moving.project.id, { title: "Third" }),
    );
    expect(third.number).toBe(3);
    expect(first.projectId).toBe(moving.project.id);

    // Moving back takes the next number of the original project, not 2.
    const back = await issueService.moveIssueToProject(moving.actors.member, {
      orgId: moving.org.id,
      issueId: second.id,
      toProjectId: moving.project.id,
    });
    expect(back.number).toBe(4);
  });

  it("changes nothing and publishes nothing when the target is the current project", async () => {
    const same = await createTenant("issuemovesame");
    const issue = await issueService.createIssue(
      same.actors.member,
      issueInput(same.org.id, same.project.id, { title: "Stays put" }),
    );

    const received: unknown[] = [];
    const off = subscribe("issue.moved", (payload) => {
      received.push(payload);
    });

    try {
      const result = await issueService.moveIssueToProject(same.actors.member, {
        orgId: same.org.id,
        issueId: issue.id,
        toProjectId: same.project.id,
      });

      expect(result).toMatchObject({ id: issue.id, projectId: same.project.id, number: 1 });
      expect(received).toHaveLength(0);
    } finally {
      off();
    }
  });

  it("refuses an actor who may not edit the issue, leaving it where it was", async () => {
    const guarded = await createTenant("issuemoveguard");
    const other = await insertOtherProject(guarded);
    const issue = await issueService.createIssue(
      guarded.actors.member,
      issueInput(guarded.org.id, guarded.project.id, { title: "Guarded" }),
    );

    await expect(
      issueService.moveIssueToProject(guarded.actors.viewer, {
        orgId: guarded.org.id,
        issueId: issue.id,
        toProjectId: other.id,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    const stillThere = await issueRepo.findIssueById(guarded.org.id, issue.id);
    expect(stillThere?.projectId).toBe(guarded.project.id);
    expect(stillThere?.number).toBe(1);
  });

  it("refuses a move into a project already at its plan issue quota", async () => {
    const full = await createTenant("issuemovequota", "free");
    const other = await insertOtherProject(full);

    // Fill the target directly through the repository, as the create quota test does.
    for (let number = 1; number <= 100; number += 1) {
      await issueRepo.insertIssue(
        issueInput(full.org.id, other.id, { title: `Seed ${number}` }),
        full.actors.member.userId,
        number,
      );
    }

    const issue = await issueService.createIssue(
      full.actors.member,
      issueInput(full.org.id, full.project.id, { title: "Too many" }),
    );

    await expect(
      issueService.moveIssueToProject(full.actors.member, {
        orgId: full.org.id,
        issueId: issue.id,
        toProjectId: other.id,
      }),
    ).rejects.toThrow(/allows no more issues/);

    const stillThere = await issueRepo.findIssueById(full.org.id, issue.id);
    expect(stillThere?.projectId).toBe(full.project.id);
  });
});

